-- Delta only: 18 newly authored quest dialogs added on 2026-07-16.
-- Safe to run in Supabase SQL Editor; uses upsert on dialog_id.
begin;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_QUEST_NEUTRAL_AMA_001', 'QUEST_NEUTRAL_AMA_001', 'NPC_NEXUS_BANKER_AMA7', 'greeting', '[{"id": "greeting", "text": "ALERT: Credent integrity breach detected. Counterfeit CRD has entered three faction markets within the same audit cycle. This is not ordinary crime; it is an attack on the trust that keeps Pax Nexus from becoming another war zone.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Credent is backed by belief, law, and Custodian force. If forged currency spreads, merchants stop accepting neutral payment, factions return to barter, and Prima Materia shipments become hostage to local armies. The AMA cannot allow a crack in the Ledger to become a fracture in peace.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "The source is an underground press hidden near the Secure Mining Grid. Its guards are not protecting coin; they are protecting a weapon of economic panic. Destroy the control units, recover counterfeit samples, and give me enough evidence to lock the exploit out of the Nexus Network.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Proceed to the Secure Mining Grid. Disable the press control units, remove the guards, recover counterfeit CRD samples, and return them to this terminal. Successful analysis will harden AMA authentication and restore market confidence before the rumor spreads.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 732)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_QUEST_NEUTRAL_AMA_002', 'QUEST_NEUTRAL_AMA_002', 'NPC_NEXUS_BANKER_AMA7', 'greeting', '[{"id": "greeting", "text": "CRISIS PROTOCOL ACTIVE. A faction currency has collapsed below survivability thresholds. If the route remains unsecured, food, medicine, and Prima Materia contracts will fail in sequence. This mission requires a full party because panic travels faster than convoys.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The AMA does not stabilize markets for profit. We do it because famine and unpaid soldiers are the oldest engines of war. The Ledger predicts border violence within forty-eight hours unless an emergency CRD package reaches the crisis capital intact.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "Speculator squads are already moving. They intend to raid the convoy, buy the wreckage cheaply, and sell the panic back to the victims. Break their assault and the Custodians can keep this collapse economic instead of military.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Escort the stabilization convoy through the Border Skirmish Ring. Clear speculator squads and confirm delivery through the AMA terminal. If the package lands, exchange rates recover, trade routes reopen, and your name is entered as a stabilizing agent in the Ledger.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 733)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_QUEST_NEUTRAL_DAILY_001', 'QUEST_NEUTRAL_DAILY_001', 'NPC_NEXUS_QUESTGIVER_ARBITER', 'greeting', '[{"id": "greeting", "text": "Peace is not maintained by speeches in the Conclave Hall. It is maintained by boots on bad roads, by border lights still burning at dawn, and by operatives willing to notice trouble before it grows teeth.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Raiders test Pax Nexus every day. Some are hungry. Some are paid by factions who want to know how far Custodian patience stretches. Routine patrols deny them that answer and reassure the small settlements caught between larger banners.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "If the border goes quiet for the wrong reason, it means someone has cleared the witnesses. Sweep the patrol line, break any raider cell you find, and return with a clean report before rumors do the work of bullets.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Patrol the Nexus border zone and eliminate the raiders threatening the neutral corridor. Your report will adjust the Custodian watch schedule and raise your standing as someone who keeps peace before it needs a fleet.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 734)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_QUEST_NEUTRAL_DAILY_002', 'QUEST_NEUTRAL_DAILY_002', 'NPC_NEXUS_BANKER_AMA7', 'greeting', '[{"id": "greeting", "text": "Request: field samples required. The Ledger is receiving contradictory production reports from faction territories. Someone is either lying about resource output or the Aethel is shifting under their feet.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Exchange rates are not abstract numbers on Xylos. One bad index can starve a frontier clinic, bankrupt a caravan, or make a warlord think invasion is cheaper than trade. Material samples give the AMA a truth no minister can edit.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "Collect common resource samples from the field. The value is not in rarity; it is in pattern integrity. If the samples expose manipulation, the AMA can correct the market before opportunists weaponize the error.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Gather material samples and submit them to the AMA. The resulting index update will stabilize local exchange calculations and quietly protect thousands of small trades from predatory pricing.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 735)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_QUEST_NEUTRAL_DAILY_003', 'QUEST_NEUTRAL_DAILY_003', 'NPC_NEXUS_QUESTGIVER_SMUGGLER', 'greeting', '[{"id": "greeting", "text": "I''ve got a package that needs to reach Delta. Before you ask, yes, it''s legal. Mostly. Legal enough that nobody important should be shooting at you unless somebody lied to me, and people lie to me professionally.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Extraction Zone Delta is a corporate throat with too many hands around it. OmniCorp watches the roads, the Cartel watches OmniCorp, and the Custodians pretend not to watch either until someone bleeds in public. This delivery keeps a contact alive and a ledger from changing hands.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "Interceptors are going to hit you before the drop. If they get the package, they''ll know who has been moving information through the Shadow Bazaar. If they know that, several useful people become corpses before sunset.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Reach the Delta drop point, survive the ambush, and hand the package to my contact. Do it clean and I''ll make sure the Bazaar remembers you as reliable, which is rarer than honest.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 736)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_QUEST_NEUTRAL_SIDE_001', 'QUEST_NEUTRAL_SIDE_001', 'NPC_NEXUS_MERCHANT_ELARA', 'greeting', '[{"id": "greeting", "text": "Those crates were not luxury goods. They were fever suppressants, wound foam, and clean filters for people who cannot afford faction medicine. Looters hit the shipment because mercy sells well when supply runs dry.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Pax Nexus survives because neutral traders keep civilians alive between faction lines. If caravans like mine fail, the small wards turn desperate, and desperate wards sell themselves to whoever offers protection first.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "The crates were dragged into the Broken Civil Quarter. Feral scavengers are guarding them now, either for resale or because someone paid them to let the sick wait. Recover what you can and clear the site before the medicine spoils.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Travel to the skirmish quarter, recover the medical crates, and remove the scavengers holding them. Bring the supplies back and the Common Market''s clinics stay open another week. That is not glamorous, but it is civilization.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 737)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_QUEST_NEUTRAL_SIDE_002', 'QUEST_NEUTRAL_SIDE_002', 'NPC_NEXUS_INFO_CHRONICLER', 'greeting', '[{"id": "greeting", "text": "A page is missing from the Galactic Archive. Not misplaced. Removed. The absence has edges, and those edges cut through every official account of an ancient faction conflict near the Aethelgardian ruins.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "History on Xylos is never dead. It is ammunition. Someone erased this page because it names a betrayal that still profits from silence. If the record vanishes completely, the next war will be built on a lie no one remembers how to question.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "The fragment was traced to a hidden vault in the Secure Mining Grid. Automatons guard the vault, but they are not the true danger. The true danger is returning with proof and discovering who fears it.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Recover the archive data fragments, retrieve the lost page, and bring it back to the Archive Spire. I will restore it to the public record. Reputation shifts slowly, but truth shifts the ground beneath it.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 738)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_QUEST_NEUTRAL_SIDE_003', 'QUEST_NEUTRAL_SIDE_003', 'NPC_NEXUS_BLACKSMITH_VULKAN', 'greeting', '[{"id": "greeting", "text": "A commission came across my anvil with no patron name and enough CRD to make a coward ask fewer questions. Legendary weapon, neutral make, faction materials. That combination either ends a war or starts one.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Iron alloy, Arcanum crystal, and Starforged ore do not like sharing the same forge. Neither do the people who own them. But if I can bind them around a tempered Aethel channel, Pax Nexus gains proof that rival powers can become one instrument without breaking.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "Bring me clean materials from the faction regions. No stolen ceremonial relics, no cursed scrap, no singing stones unless they sing on key. If the components are flawed, the weapon becomes a political incident with a blade attached.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Gather the alloy, crystal cores, and stellar ore, then return to the Crucible. If the forge holds, the finished work will stand as a neutral masterpiece and your reputation will carry the ring of every hammer strike.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 739)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_QUEST_NEUTRAL_SPECIAL_001', 'QUEST_NEUTRAL_SPECIAL_001', 'NPC_NEXUS_DIPLOMAT_VAEL', 'greeting', '[{"id": "greeting", "text": "The summit table is set, which means every enemy of peace now knows where to aim. Delegates from rival factions will walk into one room and pretend their guards are not measuring each other for coffins.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Trade is the first language spoken after war becomes too expensive. If this summit succeeds, border tariffs soften, prisoner exchanges become possible, and small settlements get breathing room. If it fails, every faction blames the others and the Custodians inherit a battlefield.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "Assassins have entered the Black Dock routes under false cargo seals. They do not need to kill every delegate. One corpse, placed correctly, can murder the treaty. Secure the approach, escort the delegates, and break the final strike before panic owns the hall.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Neutralize summit disruptors, escort both delegates to Nexus Core, and defeat the elite assassins sent to collapse the talks. Success will move the world state toward fragile cooperation and earn both Custodian and faction recognition.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 740)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_QUEST_NEUTRAL_STORY_001', 'QUEST_NEUTRAL_STORY_001', 'NPC_NEXUS_QUESTGIVER_ARBITER', 'greeting', '[{"id": "greeting", "text": "I have seen wars begin with less than this. Illegal weapons are moving through Black Dock Market, and they are being sold to both sides of a border dispute. Someone wants a spark and is patient enough to buy the tinder first.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Custodians do not intervene because factions dislike each other. We intervene when private ambition begins shaping mass graves. These caches are not defensive stockpiles; their serial ghosts point to a broker who profits only if peace fails.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "Go to Black Dock, break the arms route, and recover the caches before they vanish into uniforms. If we can prove a third party is arming both sides, the Conclave can freeze the escalation before commanders start calling revenge justice.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Investigate Black Dock Market, neutralize the arms dealers, recover the illegal caches, and return the evidence to me. This will open a Custodian inquiry and mark you as an operative trusted with the weight of peace.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 741)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_QUEST_NEUTRAL_STORY_002', 'QUEST_NEUTRAL_STORY_002', 'NPC_NEXUS_QUESTGIVER_COMMANDER', 'greeting', '[{"id": "greeting", "text": "Your evidence was not the end of the thread. It was the knot. The same shadow ledger appears behind shell caravans, hired blades, and propaganda bursts across three faction borders.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Whoever is moving these pieces understands the Custodians too well. They provoke small conflicts below intervention threshold, then harvest the chaos for components and loyalties. That is strategy, not smuggling.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "We need structure: names, routes, funding, command signals. Infiltrate Black Dock before the organization burns its local hub. If you are detected, extract anyway. Intelligence in your hand is worth more than silence in your grave.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Enter the smuggling hub, gather intel drives, eliminate shadow enforcers during extraction, and bring the fragments to Sentinel Command. The data will decide whether this becomes a police action or a war council matter.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 742)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_QUEST_NEUTRAL_STORY_003', 'QUEST_NEUTRAL_STORY_003', 'NPC_NEXUS_DIPLOMAT_VAEL', 'greeting', '[{"id": "greeting", "text": "The intelligence names a Custodian officer. A former dreadnought captain, sworn to prevent existential threats, is building one under the cover of faction unrest. I wish I could tell you this is impossible.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Custody survives because the galaxy believes our restraint is stronger than our weapons. If a rogue commander assembles planet-killer components on Xylos, every faction will see our mandate as hypocrisy wearing armor.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "The Conclave session begins soon. We need proof, recovered components, and the commander neutralized before he can invoke emergency authority. This is a raid-level breach. Bring allies. Bring discipline. Bring back enough truth that no one can bury it.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Breach the hidden fortress, secure the precursor weapon caches, defeat the rogue commander, and return to me with proof. Success prevents a planetary crisis and forces the Custodians to confront corruption within their own shield.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 743)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_merid_083', 'fq_merid_083', 'npc_cartel_boss', 'greeting', '[{"id": "greeting", "text": "The Hidden Aethelgardian City is on our books now, but ownership without paperwork is just poetry with witnesses. I need the kind of deed that makes kings, ghosts, and judges all shut up at once.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Aethelgardians wrote property law like a curse: bloodline, memory, resonance, and seal. Rival buyers are already sniffing around the registry district. If they find a Precursor deed before we do, they can dispute our claim in every court that still fears old signatures.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "The Reavers have nested around the deed seals. Maybe they like the resonance. Maybe history itself is trying to bite our hands off. Remove the hostile claimants and recover the registry fragments before someone else turns ancient law into modern leverage.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Recover the Precursor deed seals from the Reaver nests and clear the registry district. Bring them to me, and the Cartel doesn''t just own ruins; we own the argument about who gets to profit from the past.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 744)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_omni_008', 'fq_omni_008', 'npc_extraction_chief', 'greeting', '[{"id": "greeting", "text": "The Delta Mining Drones did not malfunction. They obeyed corrupted instructions from a processor node buried beneath the survey grid. Random failure is an expense. Contagion is a liability.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Aethel contamination is not mystical when it reaches OmniCorp hardware. It is a propagation vector. If the defect jumps from mining drones into security systems, Extraction Zone Delta becomes a hostile asset with our logo still on it.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "The contaminated node has escorts because the corruption learned to protect its source. Dismantle the drones, recover the circuit fragment, and preserve the failure chain. I want proof precise enough to survive an executive audit.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Enter the survey grid, dismantle the Delta Mining Drone escorts, and return with the corrupted circuit fragment. Once isolated, we patch the fleet, protect the extraction schedule, and bill the disaster to the correct department.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 745)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_msq_tutorial_01', 'msq_tutorial_01', 'npc_class_advisor', 'greeting', '[{"id": "greeting", "text": "Welcome to Xylos, candidate. The city lights make Nexus look safe, but beyond the gates the Aethel still remembers the Great Severance. Your first lesson is simple: survival is a skill, not a promise.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Every faction will ask who you are. Do not answer with a title yet. Answer with action. Step into the field, face a real threat, and learn how your body reacts when the old world bares its teeth.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "Win your first battle and return alive. The result will calibrate your combat record, open your early progression path, and prove that you are more than another name passing through the terminal.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Open Explore and win your first battle. When you do, your record begins, your rewards unlock, and Guide Axiom will move you to the next step of becoming someone Xylos must notice.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 746)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_msq_tutorial_02', 'msq_tutorial_02', 'npc_class_advisor', 'greeting', '[{"id": "greeting", "text": "You survived first contact. Good. Now comes the quieter danger: growth without direction. Xylos rewards power, but it punishes waste.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Each level leaves a choice in your hands. Strength, agility, vitality, intelligence, and the rest are not numbers on a panel; they are the shape of the person who walks into the next ruin and the person who walks out.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "Reach Level 2, then spend your stat point with intent. A careless distribution can make a warrior too fragile, a caster too slow, or a survivor too weak to end the fight before attrition does.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Reach Level 2 and assign your stat point in Profile. That decision becomes part of your build identity and prepares you for class selection later.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 747)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_msq_tutorial_03', 'msq_tutorial_03', 'npc_class_advisor', 'greeting', '[{"id": "greeting", "text": "Your readings are stabilizing. At Level 5, the system will ask what discipline can carry your instincts forward. A class is not a costume; it is a contract with your future self.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The factions will all try to define you. Choose your calling before they do. The ruins of Aethelgard do not care whether you swing steel, channel Aethel, or outthink the dark. They care whether your path has purpose.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "Reach Level 5 and choose your class. This unlocks your first true combat identity, shapes your skill growth, and tells every trainer on Xylos what kind of weapon you are becoming.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Reach Level 5, speak with the class systems, and choose your class. Once chosen, your progression stops being generic and starts becoming yours.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 748)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_msq_tutorial_04', 'msq_tutorial_04', 'npc_class_advisor', 'greeting', '[{"id": "greeting", "text": "You have survived, grown, and chosen a path. Now Xylos asks for allegiance in deed. A faction is more than a banner; it is the version of the future you are willing to strengthen.", "options": [{"text": "Tell me why this matters.", "next": "lore", "action": ""}, {"text": "What happens if we fail?", "next": "stakes", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Concordium seeks order through restoration. Arcanum seeks truth even where truth burns. Hegemony trusts iron. Meridian trusts leverage. OmniCorp trusts profit. The Shard listens for divinity. The Legion fights for rebirth. Your first faction mission is where philosophy becomes consequence.", "options": [{"text": "What is at stake?", "next": "stakes", "action": ""}, {"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "stakes", "text": "Accept your faction''s first mission and the world begins tracking you as more than a traveler. Reputation opens doors, closes others, and ties your victories to the balance of power on Xylos.", "options": [{"text": "Then we stop it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Accept your faction''s first mission from the Quest board. Completing this step ends your first directive and begins your real place in the struggle for Xylos.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 749)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
commit;
